CREATE OR REPLACE PROCEDURE public.sp_update_experience_harvest_request(IN p_id uuid, IN p_status character varying, IN p_review_notes text, IN p_reviewed_by_user_id uuid, IN p_reviewed_at timestamp with time zone, IN p_safety_suitability_verified boolean, IN p_learning_objectives_verified boolean, IN p_instructions_verified boolean, IN p_materials_verified boolean, IN p_media_rights_verified boolean, IN p_commercial_rights_verified boolean)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE experience_harvest_requests SET         status = p_status,         review_notes = p_review_notes,         reviewed_by_user_id = p_reviewed_by_user_id,         reviewed_at = p_reviewed_at,         safety_suitability_verified = p_safety_suitability_verified,         learning_objectives_verified = p_learning_objectives_verified,         instructions_verified = p_instructions_verified,         materials_verified = p_materials_verified,         media_rights_verified = p_media_rights_verified,         commercial_rights_verified = p_commercial_rights_verified     WHERE id = p_id; END; $procedure$ ;
